problems.solution:
function arrayFrom(items, mapFn, thisArg) {
  if (items == null) {
    throw new TypeError(items + ' is not iterable or array-like');
  }
  if (mapFn !== undefined && typeof mapFn !== 'function') {
    throw new TypeError(String(mapFn) + ' is not a function');
  }
  const convert = (value, index) =>
    mapFn ? mapFn.call(thisArg, value, index) : value;
  const out = [];
  if (typeof items[Symbol.iterator] === 'function') {
    let i = 0;
    for (const value of items) {
      out.push(convert(value, i++));
    }
    return out;
  }
  const obj = Object(items);
  const len = Math.max(0, Math.trunc(Number(obj.length)) || 0);
  for (let i = 0; i < len; i++) {
    out.push(convert(obj[i], i));
  }
  return out;
}

