problems.solution:
Array.prototype.myIncludes = function (searchElement, fromIndex) {
  if (this == null) {
    throw new TypeError('Array.prototype.myIncludes called on null or undefined');
  }
  const arr = Object(this);
  const len = arr.length >>> 0;
  if (len === 0) return false;
  const n = Math.trunc(Number(fromIndex)) || 0;
  let i = n >= 0 ? n : Math.max(len + n, 0);
  for (; i < len; i++) {
    const item = arr[i];
    if (item === searchElement) return true;
    if (item !== item && searchElement !== searchElement) return true;
  }
  return false;
};

