problems.solution:
function prepare(text, search) {
  if (text == null) {
    throw new TypeError('String method called on null or undefined');
  }
  if (search instanceof RegExp) {
    throw new TypeError('First argument must not be a regular expression');
  }
  return [String(text), String(search)];
}

function clamp(n, len) {
  const x = Math.trunc(Number(n)) || 0;
  return Math.min(Math.max(x, 0), len);
}

String.prototype.myStartsWith = function (search, position) {
  const [text, str] = prepare(this, search);
  const start = clamp(position, text.length);
  return text.slice(start, start + str.length) === str;
};

String.prototype.myEndsWith = function (search, endPosition) {
  const [text, str] = prepare(this, search);
  const end = endPosition === undefined ? text.length : clamp(endPosition, text.length);
  const start = end - str.length;
  if (start < 0) return false;
  return text.slice(start, end) === str;
};

String.prototype.myIncludes = function (search, position) {
  const [text, str] = prepare(this, search);
  const start = clamp(position, text.length);
  for (let i = start; i + str.length <= text.length; i++) {
    if (text.slice(i, i + str.length) === str) return true;
  }
  return false;
};

